const lecturaDB = $("Postgres - Leer Sesion").first().json || {};
const rawJson = $("Code in JavaScript").first().json;
const body = rawJson.body || rawJson;

function sanitize(str) {
  if (!str) return '';
  return str
    .replace(/[\u2018\u2019\u201A\u201B\u201C\u201D\u201E\u201F]/g, function(c) {
      return ['\u2018','\u2019','\u201A','\u201B'].includes(c) ? "'" : '"';
    })
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/[\u2026]/g, '...');
}

const rawMessage = (body.message || '').trim();
const message = sanitize(rawMessage);
const sessionId = rawJson.sessionId || body.sessionId;
const category = body.category || 'general';
const moduloActual = lecturaDB.modulo_actual || 0;

return [{ json: {
  sessionId,
  category,
  sanitizedMessage: message,
  moduloActual,
  _debug_message: rawMessage
}}];

