function sanitize(str) {
  if (!str) return '';
  return str
    .replace(/[\u2018\u2019\u201A\u201B]/g, "'")
    .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/[\u2026]/g, '...');
}

let respuesta = '';
let sessionId = '';

// Ruta A: viene despues de Guardar Audit Trail (conversacion con agente)
// El output limpio esta en Sanitize AI Output, accesible por nombre de nodo
try {
  const sanitized = $("Sanitize AI Output").first().json;
  if (sanitized && sanitized.aiOutputClean) {
    respuesta = sanitize(sanitized.aiOutputClean);
    sessionId = sanitized.sessionId || '';
  }
} catch(e) {}

// Ruta B: viene de Welcome Message directamente
if (!respuesta) {
  try {
    const welcome = $("Welcome Message").first().json;
    if (welcome && welcome.respuesta) {
      respuesta = sanitize(welcome.respuesta);
      sessionId = welcome.sessionId || '';
    }
  } catch(e) {}
}

if (!respuesta) respuesta = 'Hubo un problema al generar la respuesta. Por favor intenta de nuevo.';

return [{ json: { tipo: 'respuesta_rag', respuesta, sessionId, proceso: null } }];

function sanitize(str) {
  if (!str) return '';
  return str
    .replace(/[\u2018\u2019\u201A\u201B]/g, "'")
    .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/[\u2026]/g, '...');
}

const aiOutput = $("AI Agent Capacitacion").first().json.output || '';
const sessionId = $("Code - Determinar Estado").first().json.sessionId;
const message = $("Code - Determinar Estado").first().json.sanitizedMessage;
const category = $("Code - Determinar Estado").first().json.category;

return [{ json: {
  aiOutputClean: sanitize(aiOutput),
  sessionId,
  messageClean: sanitize(message),
  category
}}];

const lecturaDB = $("Postgres - Leer Sesion").first().json || {};
const isNew = !lecturaDB.session_id;
const sessionId = $("Code - Determinar Estado").first().json.sessionId;
const sanitizedMessage = $("Code - Determinar Estado").first().json.sanitizedMessage;
const category = $("Code - Determinar Estado").first().json.category;
return [{ json: { sessionId, sanitizedMessage, category, isNewSession: isNew } }];

const sessionId = $("Detect New Session").first().json.sessionId;
const saludo = "Hola, bienvenido/a a la capacitacion del SGC de UNIMINUTO.\n\nSoy **AVA**, tu facilitadora para este recorrido. Vamos a explorar juntos los 6 modulos del Sistema de Gestion de Calidad: desde el contexto institucional de UNIMINUTO hasta como la calidad se vive en el trabajo diario.\n\n¿Listo/a para comenzar con el **Modulo 1 - Contexto de UNIMINUTO**?";

return [{ json: {
  tipo: 'respuesta_directa',
  respuesta: saludo,
  sessionId,
  moduloObjetivo: 0
}}];

const data = $("Detect New Session").first().json;
const sessionDB = $("Postgres - Leer Sesion").first().json || {};
const rawMsg = (data.sanitizedMessage || '').trim();
const raw = rawMsg.toLowerCase().replace(/[¿?¡!.,;:]/g, '').trim();
const sessionId = data.sessionId;
const category = data.category;

const moduloActual = (sessionDB.modulo_actual !== undefined && sessionDB.modulo_actual !== null)
  ? parseInt(sessionDB.modulo_actual) : 0;

// ── Detectar confirmacion ──────────────────────────────────
const confirmaciones = [
  'si','sí','ok','vale','dale','listo','lista','claro','vamos','sigamos',
  'continuemos','continua','continúa','siguiente','avanza','empecemos',
  'comenzemos','adelante','perfecto','entendido','de acuerdo','ya','bueno',
  'comencemos','sigue','yes','va','continuamos','bien',
  'siguiente modulo','proximo modulo','avancemos'
];
const palabras = raw.split(/\s+/);
const esConfirmacion =
  confirmaciones.some(c => raw === c) ||
  (palabras.length <= 7 && palabras.some(p => confirmaciones.includes(p))) ||
  (raw.includes('modulo') && (raw.includes('sig') || raw.includes('continu') || raw.includes('avanz'))) ||
  raw.includes('continuar') ||
  raw.includes('quiero continuar') ||
  raw.includes('sigamos con');

// ── Determinar modulo objetivo ────────────────────────────
let moduloObjetivo;
if (esConfirmacion && moduloActual < 6) moduloObjetivo = moduloActual + 1;
else if (esConfirmacion && moduloActual === 6) moduloObjetivo = 6;
else moduloObjetivo = moduloActual === 0 ? 1 : moduloActual;

// ── Modulos que necesitan RAG (solo cuando es confirmacion/avance) ─
const modulosConRAG = [1, 3, 4, 5];
const necesitaRAG = modulosConRAG.includes(moduloObjetivo) && esConfirmacion;

// ── Query por modulo para el vector search ────────────────
const ragQueryMap = {
  1: 'mision vision UNIMINUTO institucion educacion superior',
  3: 'politica de calidad UNIMINUTO SGC',
  4: 'objetivos de calidad UNIMINUTO metas',
  5: 'glosario terminos clave SGC calidad definiciones'
};
const ragQuery = necesitaRAG ? ragQueryMap[moduloObjetivo] : '';

// ── Instruccion por modulo (sin RAG aun, se inyecta despues) ─
const instruccionModulo = {
  1: 'Presenta la mision y vision de UNIMINUTO usando EXACTAMENTE el texto del contexto adjunto. Agrega 1 oracion propia de introduccion. Cierra preguntando si quedo claro.',
  2: 'Explica con tus propias palabras que es un Sistema de Gestion de Calidad, su proposito, alcance en UNIMINUTO y los beneficios para los colaboradores. Maximo 3 parrafos. Cierra preguntando si quedo claro.',
  3: 'Presenta la Politica de Calidad de UNIMINUTO usando EXACTAMENTE el texto del contexto adjunto. Agrega 1 parrafo breve sobre su significado practico. Cierra preguntando si quedo claro.',
  4: 'Lista TODOS los Objetivos de Calidad con nombre y descripcion exactos del contexto adjunto. No omitas ninguno. Cierra preguntando si quedo claro.',
  5: 'Presenta los terminos clave del SGC con sus definiciones oficiales del contexto adjunto. Organiza en lista. Cierra preguntando si quedo claro.',
  6: 'Explica con 2 o 3 ejemplos concretos como aplica la calidad en el trabajo diario de un colaborador UNIMINUTO. Cercano y practico. Cierra felicitando al usuario por completar la capacitacion.'
};

let promptBase;
if (esConfirmacion && moduloActual < 6) {
  promptBase = `[Modulo ${moduloObjetivo} de 6]\n\nInstruccion: ${instruccionModulo[moduloObjetivo]}`;
} else if (esConfirmacion && moduloActual === 6) {
  promptBase = 'El usuario completo los 6 modulos del SGC. Felicitalo calurosamente y animalo a aplicar lo aprendido en su trabajo diario en UNIMINUTO.';
} else {
  promptBase = `[Modulo en curso: ${moduloActual}]\nEl colaborador pregunta: ${rawMsg}\nResponde enfocado en el SGC de UNIMINUTO. Si es una duda sobre el modulo actual, resuelvela y vuelve a invitarlo a continuar.`;
}

return [{ json: { sessionId, category, promptBase, moduloObjetivo, necesitaRAG, ragQuery, rawMsg } }];

const prepareData = $("Prepare Agent Input").first().json;
const { promptBase, moduloObjetivo, necesitaRAG, sessionId, category } = prepareData;

let contextoRAG = '';

if (necesitaRAG) {
  try {
    const docs = $("HTTP - Fetch RAG Supabase").first().json;
    if (Array.isArray(docs) && docs.length > 0) {
      // docs viene ordenado por similarity desc desde la RPC
      // filtramos similarity > 0.5 para no incluir docs irrelevantes
      const relevantes = docs.filter(d => (d.similarity || 0) > 0.5);
      const fuente = relevantes.length > 0 ? relevantes : docs.slice(0, 3);
      contextoRAG = fuente.map(d => d.content || '').filter(Boolean).join('\n\n');
    }
  } catch(e) {
    contextoRAG = '';
  }
}

const bloqueRAG = contextoRAG
  ? `\n\n[CONTEXTO OFICIAL UNIMINUTO - reproduce este texto con fidelidad]:\n${contextoRAG}`
  : '';

const agentInput = `${promptBase}${bloqueRAG}`;

return [{ json: { sessionId, category, agentInput, moduloObjetivo } }];

